code.css:
/* ===========================================================================
   Image compressor. Everything is scoped to .ic so nothing here can leak
   into another CMS tool. Only the tokens listed in the design system are
   used; no new custom properties are invented.
   The base embed sheet is injected before this one, so every rule below
   wins on cascade order at equal specificity.
   =========================================================================== */

.ic{
  font-family: var(--font-sans);
  font-size: var(--t-16);
  line-height: 1.55;
  color: var(--ink);
}
.ic *{ box-sizing: border-box; }
.ic [hidden]{ display: none !important; }
.ic p{ margin: 0; }
.ic button{ font-family: var(--font-sans); }
.ic button:hover,
.ic .btn:hover,
.ic button:active,
.ic .btn:active{ transform: none; }          /* the base sheet lifts buttons; this design does not */
.ic :focus-visible{ outline: 2px solid var(--accent); outline-offset: 2px; border-radius: var(--r-sm); }

/* screen-reader-only, used for the real file input */
.ic-sr{
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0 0 0 0); clip-path: inset(50%);
  white-space: nowrap; border: 0;
}

/* uppercase micro-label, the one 12px style in the system */
.ic-mlabel,
.ic-drop-hint,
.ic-cap,
.ic-counters,
.ic-privacy,
.ic .s-label,
.ic-zval{
  font: 400 var(--t-12)/1.2 var(--font-mono);
  letter-spacing: .09em;
  text-transform: uppercase;
  color: var(--muted);
}
.ic-mlabel{ display: block; }

/* --------------------------------------------------------------- buttons */
.ic .btn{
  display: inline-flex; align-items: center; justify-content: center; gap: var(--s2);
  height: var(--control-h); padding: 0 18px;
  font: 500 var(--t-14)/1 var(--font-sans); letter-spacing: .005em;
  color: var(--ink); background: var(--surface);
  border: 1px solid var(--line-strong); border-radius: var(--r-sm);
  box-shadow: var(--e-btn); cursor: pointer;
  transition: background var(--d-fast) linear, border-color var(--d-fast) linear;
}
.ic .btn:hover{ background: var(--surface-2); }
.ic .btn:active{ background: var(--surface-3); box-shadow: none; }
.ic .btn:disabled{ opacity: .5; cursor: not-allowed; }
.ic .btn-primary{
  background: var(--ink); border-color: var(--ink); color: var(--on-ink);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.10);
}
.ic .btn-primary:hover{ background: var(--ink); border-color: var(--ink); opacity: .92; }
.ic .btn-primary:active{ box-shadow: none; opacity: 1; }

/* ---------------------------------------------------------------- inputs */
.ic input[type="number"],
.ic select{
  width: 100%; min-width: 0;
  height: var(--control-h); padding: 0 14px;
  background-color: var(--surface-2); color: var(--ink);
  border: 1px solid var(--line-strong); border-radius: var(--r-sm);
  box-shadow: var(--e-well);
  font: 400 16px/1.4 var(--font-sans);       /* 16px MANDATORY, anything less zooms iOS on focus */
  -webkit-appearance: none; appearance: none;
  transition: background-color var(--d-fast) linear, border-color var(--d-fast) linear;
}
/* keep the custom chevron; the native one cannot be recolored */
.ic select{
  cursor: pointer; padding-right: 34px;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='%236B6862' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'><path d='M6 9l6 6 6-6'/></svg>");
  background-repeat: no-repeat;
  background-position: right 10px center;
  background-size: 16px 16px;
}
.ic input[type="number"]:focus,
.ic select:focus{
  background-color: var(--surface); border-color: var(--accent);
  outline: 2px solid var(--accent); outline-offset: 1px;
}
.ic input[type="range"]{
  display: block; width: 100%; height: 44px;   /* 44px keeps the drag target thumb-sized */
  margin: 0; padding: 0; border: 0; background: none; box-shadow: none;
  accent-color: var(--accent); cursor: pointer;
}
.ic input[type="range"]:disabled{ cursor: not-allowed; opacity: .45; }

/* -------------------------------------------------------------- dropzone */
.ic-drop{
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: var(--s2);
  min-height: 132px; padding: var(--s4);
  text-align: center; cursor: pointer;
  background: var(--surface-2);
  border: 1px solid var(--line-strong);        /* never dashed */
  border-radius: var(--r-md);
  box-shadow: var(--e-well);
  transition: background var(--d-fast) linear, border-color var(--d-fast) linear;
}
.ic-drop.is-over{ background: var(--surface); border-color: var(--accent); }
.ic-drop-icon{ display: block; color: var(--muted); }
.ic-drop-title{ font-size: var(--t-16); font-weight: 500; color: var(--ink); }
.ic-drop .btn{ margin: 2px 0; }

/* --------------------------------------------------------------- presets */
.ic-presets{
  display: flex; gap: var(--s2);
  margin-top: var(--s5);
  padding: 4px 0 8px;                          /* room for the 44px hit areas + scrollbar */
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}
.ic-preset-line{
  margin-top: var(--s1);
  font: 400 var(--t-14)/1.4 var(--font-sans);
  color: var(--muted);
}
.ic-chip{
  position: relative; flex: 0 0 auto; scroll-snap-align: start;
  display: inline-flex; align-items: center; justify-content: center;
  height: 36px; padding: 0 var(--s3);
  font: 500 13px/1 var(--font-sans);
  color: var(--ink); background: var(--surface);
  border: 1px solid var(--line-strong); border-radius: var(--r-sm);
  box-shadow: var(--e-btn);
  white-space: nowrap; cursor: pointer;
  transition: background var(--d-fast) linear, border-color var(--d-fast) linear, color var(--d-fast) linear;
}
/* the chip reads as 36px but answers to a 44px touch */
.ic-chip::before{
  content: ""; position: absolute; left: 0; right: 0; top: 50%;
  height: 44px; transform: translateY(-50%);
}
.ic-chip:hover{ background: var(--surface-2); }
.ic-chip.is-active{
  background: var(--ink); border-color: var(--ink); color: var(--on-ink); box-shadow: none;
}
.ic-chiprow{
  display: flex; flex-wrap: wrap; gap: var(--s2);
  margin-top: var(--s3); padding: 4px 0;
}

/* ------------------------------------------------------ target + custom */
.ic-block,
.ic-custom{
  margin-top: var(--s5); padding-top: var(--s5);
  border-top: 1px solid var(--line);
}
.ic-target-grid{
  display: grid; grid-template-columns: minmax(0,1fr) 104px; gap: var(--s2);
  margin-top: var(--s2); max-width: 360px;
}
.ic-ctl + .ic-ctl{ margin-top: var(--s5); }
.ic-ctl-head{ display: flex; align-items: baseline; justify-content: space-between; gap: var(--s3); }
.ic-ctl input[type="number"]{ margin-top: var(--s2); max-width: 200px; }
.ic-qword{ font: 500 var(--t-14)/1.4 var(--font-sans); color: var(--ink); }
.ic-qsize{
  font: 400 var(--t-14)/1.4 var(--font-mono);
  font-variant-numeric: tabular-nums slashed-zero; font-feature-settings: "tnum","zero";
  color: var(--muted);
}
.ic-hint{ margin-top: var(--s2); font: 400 var(--t-14)/1.5 var(--font-sans); color: var(--muted); }
.ic-ctl.is-off .ic-qword,
.ic-ctl.is-off .ic-qsize{ opacity: .45; }

.ic .mode-tabs{
  display: flex; gap: var(--s5);
  margin: var(--s2) 0 0; padding: 0;
  background: none; border-radius: 0;
  border-bottom: 1px solid var(--line);
  overflow-x: auto;
}
.ic .mode-tabs button{
  height: 44px; padding: 0; margin-bottom: -1px;
  border: 0; border-bottom: 2px solid transparent; border-radius: 0;
  background: none; box-shadow: none;
  font: 500 var(--t-14)/1 var(--font-sans); color: var(--muted);
  white-space: nowrap; cursor: pointer;
  transition: color var(--d-fast) linear, border-color var(--d-fast) linear;
}
.ic .mode-tabs button.active{ color: var(--ink); border-bottom-color: var(--ink); }

/* ---------------------------------------------------------------- nudges */
.ic-nudges:not(:empty){ margin-top: var(--s4); }
.ic-nudge{
  display: flex; flex-wrap: wrap; align-items: center; gap: var(--s3);
  padding: var(--s3) var(--s4);
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-left: 2px solid var(--accent);
  border-radius: var(--r-sm);
  font: 400 var(--t-14)/1.5 var(--font-sans);
  color: var(--ink-2);
}
.ic-nudge + .ic-nudge{ margin-top: var(--s2); }
.ic-nudge p{ flex: 1 1 220px; min-width: 0; }
.ic-nudge .btn{ flex: 0 0 auto; }
.ic-nudge.is-warn{
  background: var(--danger-bg);
  border-color: var(--danger-line); border-left-color: var(--danger);
  color: var(--danger);
}
.ic-nudge.is-ok{
  background: var(--ok-bg);
  border-color: var(--ok-line); border-left-color: var(--ok);
  color: var(--ok);
}

/* ------------------------------------------------------------- file list */
.ic-list{ list-style: none; margin: var(--s5) 0 0; padding: 0; }
.ic-list:empty{ margin: 0; }
.ic-row{
  position: relative;
  display: grid; grid-template-columns: 40px minmax(0,1fr) auto;
  gap: var(--s3); align-items: center;
  padding: var(--s3) 0;
  border-top: 1px solid var(--line);
}
.ic-list .ic-row:last-child{ border-bottom: 1px solid var(--line); }
.ic-thumb{
  width: 40px; height: 40px; display: block;
  object-fit: cover; border-radius: var(--r-sm);
  background: var(--surface-3); border: 1px solid var(--line);
  cursor: pointer;
}
.ic-row.is-sel .ic-thumb{ outline: 2px solid var(--accent); outline-offset: 1px; }
/* The thumbnail is the control that picks which file the compare viewport
   shows, so it is a button. It carries no chrome of its own: the framed 40px
   image inside it is the whole affordance, and the base embed sheet's button
   background, border and padding are reset off here. */
.ic-thumbbtn{
  position: relative; display: block;
  width: 40px; height: 40px; padding: 0;
  border: 0; background: none; box-shadow: none; cursor: pointer;
}
/* Same 44px overlay the chips, segments, zoom and row buttons get. */
.ic-thumbbtn::before{
  content: ""; position: absolute; left: -2px; right: -2px; top: 50%;
  height: 44px; transform: translateY(-50%);
}
.ic-meta{ min-width: 0; }
.ic-name{
  display: block; font-size: var(--t-14); line-height: 1.4; color: var(--ink);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.ic-sub{
  display: block; margin-top: 2px;
  font: 400 var(--t-12)/1.35 var(--font-mono);
  font-variant-numeric: tabular-nums slashed-zero; font-feature-settings: "tnum","zero";
  letter-spacing: .01em; color: var(--muted);
  overflow-wrap: anywhere;
}
.ic-good{ color: var(--ok); }
.ic-bad{ color: var(--danger); }
.ic-rowbtns{ display: flex; gap: var(--s2); }
/* deliberately 32px: three of these plus a thumbnail must fit a 343px row */
.ic-iconbtn{
  position: relative;
  width: 32px; height: 32px; min-width: 32px; padding: 0;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--ink); background: var(--surface);
  border: 1px solid var(--line-strong); border-radius: var(--r-sm);
  box-shadow: var(--e-btn); cursor: pointer;
  transition: background var(--d-fast) linear, border-color var(--d-fast) linear;
}
/* Same 44px overlay the chips, segments and zoom buttons get. Skipped here
   originally, which left the one destructive control in the tool as the
   smallest and most crowded target: Remove has no confirm and no undo, and
   it sits 8px from Download. The row is ~64px tall so 44px fits inside it,
   and the 8px gap keeps the two overlays from colliding. */
.ic-iconbtn::before{
  content: ""; position: absolute; left: -2px; right: -2px; top: 50%;
  height: 44px; transform: translateY(-50%);
}
.ic-iconbtn:hover{ background: var(--surface-2); }
.ic-iconbtn:disabled{ opacity: .4; cursor: not-allowed; }
.ic-list.no-rowdl .ic-dl{ display: none; }
/* 2px progress bar along the bottom edge of the encoding row */
.ic-row.is-busy::after{
  content: ""; position: absolute; left: 0; bottom: 0;
  width: 100%; height: 2px; background: var(--accent);
  transform-origin: 0 50%;
  animation: ic-bar 900ms linear infinite;
}
@keyframes ic-bar{ from{ transform: scaleX(0); } to{ transform: scaleX(1); } }

/* ---------------------------------------------------------- summary strip */
.ic .stat-grid{
  display: grid; grid-template-columns: repeat(auto-fit, minmax(min(120px,100%),1fr));
  gap: 0; margin-top: var(--s5); border-top: 1px solid var(--line);
}
.ic .stat{
  background: none; border-radius: 0; text-align: left;
  padding: var(--s4) var(--s4) var(--s1) 0;
  border-left: 1px solid var(--line);
}
.ic .stat:first-child{ border-left: 0; }
.ic .stat:not(:first-child){ padding-left: var(--s4); }
.ic .s-num{
  display: block;
  font: 700 var(--t-31)/1.1 var(--font-sans); letter-spacing: -.022em;
  font-variant-numeric: tabular-nums slashed-zero; font-feature-settings: "tnum","zero";
  min-width: 6ch;                                /* the figures must never reflow the row */
  overflow-wrap: anywhere;
}
.ic .s-label{ display: block; margin-top: var(--s1); }
/* the SAVED figure only ever turns red when the batch actually grew */
.ic .s-num.ic-bad{ color: var(--danger); }

/* ------------------------------------------------------- compare viewport */
.ic-compare{ margin-top: var(--s5); }
.ic-cbar{
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;
  gap: var(--s3); margin-bottom: var(--s3);
}
.ic-seg{
  display: inline-flex; gap: 2px; padding: 4px;   /* 36 + 8 + 2 = 46px tall control */
  background: var(--surface-2);
  border: 1px solid var(--line-strong); border-radius: var(--r-sm);
  box-shadow: var(--e-well);
}
.ic-seg button{
  position: relative;
  height: 36px; min-width: 64px; padding: 0 var(--s3);
  border: 0; border-radius: 2px; background: none; box-shadow: none;
  color: var(--muted); cursor: pointer;
  font: 400 var(--t-12)/1 var(--font-mono); letter-spacing: .09em; text-transform: uppercase;
  transition: background var(--d-fast) linear, color var(--d-fast) linear;
}
.ic-seg button::before{
  content: ""; position: absolute; left: -1px; right: -1px; top: 50%;
  height: 44px; transform: translateY(-50%);
}
.ic-seg button.is-active{ background: var(--ink); color: var(--on-ink); }
.ic-seg-split{ display: none; }
.ic-zoom{ display: inline-flex; align-items: center; gap: var(--s2); }
.ic-zbtn{
  position: relative; height: 36px; padding: 0 var(--s3);
  color: var(--ink); background: var(--surface);
  border: 1px solid var(--line-strong); border-radius: var(--r-sm);
  box-shadow: var(--e-btn); cursor: pointer;
  font: 400 var(--t-12)/1 var(--font-mono); letter-spacing: .09em; text-transform: uppercase;
}
.ic-zbtn::before{
  content: ""; position: absolute; left: -2px; right: -2px; top: 50%;
  height: 44px; transform: translateY(-50%);
}
.ic-zbtn.is-active{ background: var(--ink); border-color: var(--ink); color: var(--on-ink); }
.ic-zval{ min-width: 5ch; }

/* Fixed aspect box. It must never resize as images swap, or the parent
   ResizeObserver makes the whole frame jump on every toggle.
   The cap is a plain px value, NOT 60vh: inside a frame whose height is set
   from its own content, a vh-based cap feeds straight back into the height
   measurement and the box settles at a different size on every page. */
.ic-view{
  position: relative;
  aspect-ratio: 4 / 3;
  max-height: 620px;
  overflow: hidden;
  background: var(--surface-3);
  border-radius: var(--r-md);
  touch-action: pan-y;                     /* vertical scroll passes to the parent page */
  cursor: zoom-in;
  user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;
}
.ic-view.is-zoomed{ touch-action: none; cursor: grab; }
.ic-view.is-zoomed:active{ cursor: grabbing; }
.ic-stage{ position: absolute; inset: 0; transform-origin: 0 0; }
.ic-img{
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  object-fit: contain;
  display: block; image-rendering: auto;
  pointer-events: none; -webkit-user-drag: none;
}
.ic-view[data-mode="before"] .ic-after{ opacity: 0; }
.ic-view.is-holding .ic-after{ opacity: 0; }
.ic-view[data-mode="split"] .ic-after{ clip-path: inset(0 0 0 var(--ic-split, 50%)); }
.ic-split{
  position: absolute; top: 0; bottom: 0; left: 50%;
  width: 44px; margin-left: -22px;
  display: none; cursor: ew-resize; touch-action: none;
}
.ic-view[data-mode="split"] .ic-split{ display: block; }
.ic-split::before{
  content: ""; position: absolute; top: 0; bottom: 0; left: 50%;
  width: 2px; margin-left: -1px; background: var(--on-ink);
  box-shadow: 0 0 0 1px rgba(25,24,23,.28);
}
.ic-split::after{
  content: ""; position: absolute; top: 50%; left: 50%;
  width: 32px; height: 32px; margin: -16px 0 0 -16px;
  background: var(--ink); border: 1px solid var(--on-ink);
  border-radius: var(--r-sm);
}
.ic-badge{
  position: absolute; left: var(--s3); top: var(--s3);
  padding: 4px 8px; pointer-events: none;
  background: var(--ink); color: var(--on-ink); border-radius: var(--r-sm);
  font: 400 var(--t-12)/1 var(--font-mono); letter-spacing: .09em; text-transform: uppercase;
}
.ic-cap{ margin-top: var(--s2); }

/* --------------------------------------------------------------- actions */
.ic .btn-row.ic-actions{
  display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2);
  margin-top: var(--s5); padding-top: var(--s4);
  border-top: 1px solid var(--line);
}
.ic-counters{ margin-left: auto; }
.ic .note{ margin-top: var(--s4); font: 400 var(--t-14)/1.5 var(--font-sans); color: var(--muted); }
.ic-privacy{ margin-top: var(--s2); }

/* ----------------------------------------------------------------- 375px */
@media (max-width: 560px){
  .ic .stat-grid{ grid-template-columns: 1fr 1fr; }
  .ic .stat{ border-top: 1px solid var(--line); padding: var(--s3) var(--s3) var(--s2) 0; }
  .ic .stat:nth-child(2n+1){ border-left: 0; padding-left: 0; }
  .ic .s-num{ font-size: var(--t-25); letter-spacing: -.016em; }
  .ic-cbar{ gap: var(--s2); }
  .ic-seg button{ min-width: 0; padding: 0 10px; }
  .ic .btn-row.ic-actions .btn{ flex: 1 1 auto; }
  .ic-counters{ margin-left: 0; width: 100%; }
  .ic-target-grid{ max-width: none; }
}
@media (min-width: 560px){
  /* the drag split slider only exists where there is room for it */
  .ic-seg-split{ display: inline-flex; align-items: center; justify-content: center; }
}

@media (prefers-reduced-motion: reduce){
  .ic *, .ic *::before, .ic *::after{
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
  }
  .ic-row.is-busy::after{ transform: scaleX(1); }
}

code.js:
/* ===========================================================================
   Image compressor.

   Runs inside a sandboxed srcdoc frame with allow-scripts but NO
   allow-same-origin, which rules out three things this file works around:
     - Web Workers  : an opaque origin rejects blob: worker scripts, so every
                      encode happens on the main thread and yields with rAF.
     - localStorage : throws SecurityError. Nothing is persisted, ever.
     - clipboard API: unavailable. WT.copy() exists for that, unused here.
   The frame also has no scrollbar of its own, so every preview lives inside a
   fixed aspect-ratio overflow:hidden box and WT.resize() is called once per
   settled state, never inside the debounce.
   =========================================================================== */
(function () {
  'use strict';

  var $ = function (id) { return document.getElementById(id); };
  var root = $('ic');
  if (!root) return;

  /* ----------------------------------------------------------- constants */

  var DEBOUNCE_MS = 200;
  var MAX_ENCODES = 10;                 // hard cap per file for target bisection
  var MAX_AREA    = 16000000;           // iOS Safari canvas backing-store ceiling
  var IOS_MAX_SIDE = 4096;
  var ZIP_LIMIT   = 4200000000;         // 32-bit offsets in the ZIP central directory
  var MAX_FILES   = 40;                 // a phone tab dies long before this many
  // Total decoded pixels held between runs. Past this the bitmaps are dropped
  // after every encode and decoded again on demand, which costs one extra JPEG
  // decode per file but stops twenty 12MP photos from taking ~1 GB of RGBA.
  var PIXEL_BUDGET = 80000000;

  var IS_IOS = /iP(hone|od|ad)/.test(navigator.userAgent) ||
               (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

  var ICON_DL = 'M12 3v11M7.5 10.5L12 15l4.5-4.5M4 20h16';
  var ICON_X  = 'M6 6l12 12M18 6L6 18';

  var PRESETS = {
    balanced: { fmt: 'auto',       q: 0.82, mw: 0,    target: 0,       blurb: 'Good savings, no visible change.' },
    portal:   { fmt: 'image/jpeg', q: 0.82, mw: 1200, target: 204800,  blurb: 'Fits exam, visa, Aadhaar and job portal limits.' },
    web:      { fmt: 'image/webp', q: 0.80, mw: 1600, target: 0,       blurb: 'Fast pages, best for WordPress.' },
    email:    { fmt: 'image/jpeg', q: 0.82, mw: 1600, target: 1048576, blurb: 'Gets under Gmail and Outlook limits.' },
    social:   { fmt: 'image/jpeg', q: 0.85, mw: 1080, target: 0,       blurb: 'Instagram, X and LinkedIn.' },
    product:  { fmt: 'image/webp', q: 0.85, mw: 2000, target: 0,       blurb: 'Shopify, Etsy and eBay.' },
    thumb:    { fmt: 'image/webp', q: 0.75, mw: 400,  target: 0,       blurb: 'Small square images and profile pictures.' },
    squeeze:  { fmt: 'image/webp', q: 0.60, mw: 1200, target: 0,       blurb: 'Smallest possible, some quality loss.' },
    custom:   { blurb: 'Your own settings.' }
  };

  /* --------------------------------------------------------------- state */

  // Cold start is Balanced: keep the original format. Portals want JPG, and a
  // large share of visitors are here because a portal just rejected a file.
  var S = { preset: 'balanced', fmt: 'auto', q: 0.82, mw: 0, target: 0 };

  var items = [];
  var seq = 0;
  var runToken = 0;
  var debounceT = null;
  var preparing = false;
  var prepToken = 0;
  var dlCount = 0;
  var selectedId = null;
  var jpegFallback = false;
  var rejected = [];
  var overflow = 0;
  var running = false;

  /* ------------------------------------------------------------ elements */

