  // deflating them costs CPU for roughly nothing.
  var CRC_TABLE = (function () {
    var t = new Uint32Array(256), c, n, k;
    for (n = 0; n < 256; n++) {
      c = n;
      for (k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      t[n] = c >>> 0;
    }
    return t;
  })();

  function crc32(u8) {
    var c = 0xFFFFFFFF;
    for (var i = 0; i < u8.length; i++) c = CRC_TABLE[(c ^ u8[i]) & 0xFF] ^ (c >>> 8);
    return (c ^ 0xFFFFFFFF) >>> 0;
  }

  function dosTime(d) { return ((d.getHours() & 31) << 11) | ((d.getMinutes() & 63) << 5) | ((d.getSeconds() / 2) & 31); }
  function dosDate(d) { return (((d.getFullYear() - 1980) & 127) << 9) | (((d.getMonth() + 1) & 15) << 5) | (d.getDate() & 31); }

  // Names carry whatever script the user's files were named in, so they go in
  // as UTF-8 with general-purpose bit 11 set. APPNOTE 4.4.4 defines that flag
  // as "filename is UTF-8", and Info-ZIP, .NET, macOS Archive Utility and
  // Windows Explorer all honour it. Masking to 7 bits instead, as this used
  // to, turned every Devanagari or Japanese name into the same placeholder.
  var UTF8_FLAG = 0x0800;

  function utf8(s) {
    if (typeof TextEncoder === 'function') return new TextEncoder().encode(s);
    // Hand-rolled fallback so the ZIP never depends on one global.
    var out = [], i, c, j;
    for (i = 0; i < s.length; i++) {
      c = s.charCodeAt(i);
      if (c >= 0xD800 && c <= 0xDBFF && i + 1 < s.length) {
        j = s.charCodeAt(i + 1);
        if (j >= 0xDC00 && j <= 0xDFFF) { c = 0x10000 + ((c - 0xD800) << 10) + (j - 0xDC00); i++; }
      }
      if (c < 0x80) out.push(c);
      else if (c < 0x800) out.push(0xC0 | (c >> 6), 0x80 | (c & 63));
      else if (c < 0x10000) out.push(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
      else out.push(0xF0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    }
    return new Uint8Array(out);
  }

  function zipStore(entries) {
    var now = new Date(), dt = dosTime(now), dd = dosDate(now);
    var parts = [], central = [], offset = 0, i;

    for (i = 0; i < entries.length; i++) {
      var name = utf8(entries[i].name);
      var data = entries[i].bytes;
      var crc = crc32(data);

      var lh = new Uint8Array(30 + name.length);
      var lv = new DataView(lh.buffer);
      lv.setUint32(0, 0x04034B50, true);   // PK\x03\x04
      lv.setUint16(4, 20, true);           // version needed
      lv.setUint16(6, UTF8_FLAG, true);    // flags: bit 11 = UTF-8 filename
      lv.setUint16(8, 0, true);            // method 0 = STORE
      lv.setUint16(10, dt, true);
      lv.setUint16(12, dd, true);
      lv.setUint32(14, crc, true);
      lv.setUint32(18, data.length, true); // compressed size
      lv.setUint32(22, data.length, true); // uncompressed size
      lv.setUint16(26, name.length, true);
      lv.setUint16(28, 0, true);           // extra field length
      lh.set(name, 30);

      var cd = new Uint8Array(46 + name.length);
      var cv = new DataView(cd.buffer);
      cv.setUint32(0, 0x02014B50, true);   // PK\x01\x02
      cv.setUint16(4, 20, true);           // version made by
      cv.setUint16(6, 20, true);           // version needed
      cv.setUint16(8, UTF8_FLAG, true);    // flags: bit 11 = UTF-8 filename
      cv.setUint16(10, 0, true);           // method 0 = STORE
      cv.setUint16(12, dt, true);
      cv.setUint16(14, dd, true);
      cv.setUint32(16, crc, true);
      cv.setUint32(20, data.length, true);
      cv.setUint32(24, data.length, true);
      cv.setUint16(28, name.length, true);
      cv.setUint16(30, 0, true);           // extra
      cv.setUint16(32, 0, true);           // comment
      cv.setUint16(34, 0, true);           // disk number
      cv.setUint16(36, 0, true);           // internal attrs
      cv.setUint32(38, 0, true);           // external attrs
      cv.setUint32(42, offset, true);      // local header offset
      cd.set(name, 46);

      parts.push(lh, data);
      central.push(cd);
      offset += lh.length + data.length;
    }

    var cdSize = 0;
    for (i = 0; i < central.length; i++) cdSize += central[i].length;

    var eo = new Uint8Array(22);
    var ev = new DataView(eo.buffer);
    ev.setUint32(0, 0x06054B50, true);     // PK\x05\x06
    ev.setUint16(4, 0, true);
    ev.setUint16(6, 0, true);
    ev.setUint16(8, entries.length, true);
    ev.setUint16(10, entries.length, true);
    ev.setUint32(12, cdSize, true);
    ev.setUint32(16, offset, true);
    ev.setUint16(20, 0, true);

    return new Blob(parts.concat(central, [eo]), { type: 'application/zip' });
  }

  function readBytes(blob) {
    if (blob.arrayBuffer) return blob.arrayBuffer().then(function (b) { return new Uint8Array(b); });
    return new Promise(function (res, rej) {
      var r = new FileReader();
      r.onload = function () { res(new Uint8Array(r.result)); };
      r.onerror = function () { rej(new Error('read')); };
      r.readAsArrayBuffer(blob);
    });
  }

  function uniqueName(name, used) {
    if (!used[name]) { used[name] = 1; return name; }
    var m = /^(.*?)(\.[^.]*)?$/.exec(name);
    var stem = m[1], ext = m[2] || '', n = 1, cand;
    do { cand = stem + '-' + n + ext; n++; } while (used[cand]);
    used[cand] = 1;
    return cand;
  }

  /* ------------------------------------------------------------ downloads */

  function downloadBlob(blob, name) {
    // A fresh URL per download so the compare viewport's URL is never revoked
    // out from under it.
    var url = URL.createObjectURL(blob);
    try {
      var a = document.createElement('a');
      a.href = url; a.download = name; a.rel = 'noopener';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    } catch (e) {
      window.open(url, '_blank');
    }
    setTimeout(function () { URL.revokeObjectURL(url); }, 8000);
  }

  function downloadOne(it) {
    // `stale` is the whole test, and it is exactly what the button's disabled
    // state is painted from. A row that has already been re-encoded in the run
    // still in flight holds a blob that matches the settings on screen, so it
    // may be served; gating on `running` as well left that row's button
    // enabled but dead for the rest of the batch.
    if (it.err || !it.out || it.stale) return;
    downloadBlob(it.keepOriginal ? it.file : it.out, outName(it));
    dlCount++;
    if (dlCount >= 3) {
      elList.classList.add('no-rowdl');
      setNote('Browsers throttle repeated downloads, so use Download all (ZIP) from here.');
      updateNudges();
    } else {
      setNote('Saved ' + outName(it) + ' to your downloads.');
    }
    settle();
  }

  function downloadZip() {
    // A run in flight, or a debounce about to start one, means half the rows
    // still hold the previous settings' blob. Zipping now would hand back an
    // archive that silently mixes old and new output, and on a format switch
    // a mix of .webp and .jpg entries.
    if (running || debounceT) return;
    var ready = items.filter(function (i) { return !i.err && i.out && !i.stale; });
    if (!ready.length) return;

    var label = elZip.textContent;
    elZip.disabled = true;
    elZip.textContent = 'Building ZIP…';

    var used = Object.create(null), entries = [], total = 0, i = 0;

    function step() {
      if (i >= ready.length) return Promise.resolve();
      var it = ready[i++];
      var blob = it.keepOriginal ? it.file : it.out;
      return readBytes(blob).then(function (u8) {
        total += u8.length;
        entries.push({ name: uniqueName(outName(it), used), bytes: u8 });
        return raf();
      }).then(step);
    }

    step().then(function () {
      if (total > ZIP_LIMIT) throw new Error('too big');
      var zip = zipStore(entries);
      downloadBlob(zip, 'compressed-images.zip');
      setNote('ZIP with ' + entries.length + ' image' + (entries.length === 1 ? '' : 's') + ' saved to your downloads.');
    }).catch(function () {
      setNote('That batch is too large to put in one ZIP. Remove a few files and try again.');
    }).then(function () {
      elZip.textContent = label;
      updateZip();               // never blindly re-enable; a run may have started
      settle();
    });
  }

  /* ----------------------------------------------------------- file input */

  function addFiles(list) {
    var arr = [];
    if (list) for (var i = 0; i < list.length; i++) arr.push(list[i]);
    if (!arr.length) return;

    // Both of these describe the drop that just happened, not the session.
    // Left to accumulate, one stray PDF pinned "Skipped one file that is not
    // an image" to the top of the tool for good.
    rejected = [];
    overflow = 0;

    var added = 0;
    arr.forEach(function (f) {
      var ok = /^image\//i.test(f.type || '') ||
               /\.(jpe?g|png|webp|gif|bmp|avif|heic|heif)$/i.test(f.name || '');
      if (!ok) { rejected.push(f.name || 'unnamed file'); return; }
      // Selecting a folder can hand over hundreds of files. Decoding them all
      // is how a phone tab dies with the whole batch and no partial result.
      if (items.length >= MAX_FILES) { overflow++; return; }
      var it = {
        id: ++seq, file: f, name: f.name || 'image',
        srcBytes: f.size, srcType: String(f.type || '').toLowerCase(),
        src: null, srcUrl: null, thumb: '',
        out: null, outUrl: null, outMime: null, outW: 0, outH: 0, outQ: 0,
        hasAlpha: null, err: null, status: 'pending',
        keepOriginal: false, bigger: false, guard: false, hitTarget: true,
        stale: false, dead: false, el: null,
        // hold: non-zero while an encode is using it.src.el, so the budget
        // evictor cannot close the bitmap underneath it.
        // pending: the in-flight decode, shared by every concurrent caller.
        hold: 0, pending: null
      };
      items.push(it);
      buildRow(it);
      added++;
    });

    updateNudges();
    if (!added && !overflow) setNote('None of those were images, so nothing was added.');
    settle();
    if (added) prepare();
  }

  function prepare() {
    if (preparing) return;
    preparing = true;
    var pt = ++prepToken;

    function next() {
      if (pt !== prepToken) return Promise.resolve();
      var it = null;
      for (var i = 0; i < items.length; i++) {
        if (!items[i].src && !items[i].err) { it = items[i]; break; }
      }
      if (!it) return Promise.resolve();

      it.status = 'decoding';
      paintRow(it);

      return raf().then(function () {
        // No HEIC pre-check by filename. Safari decodes HEIC natively, and
        // refusing it up front blocked the one browser where it works, on
        // the tool's primary device. The rejection branch below already
        // labels a genuine decode failure as HEIC, which is what B6.5 asks
        // for on Chrome and Android.
        it.srcUrl = URL.createObjectURL(it.file);
        return decodeFile(it.file, it.srcUrl).then(function (src) {
          // Clear or Remove can land while this decode is in flight.
          if (it.dead || pt !== prepToken) {
            if (src.kind === 'bitmap' && src.el && src.el.close) {
              try { src.el.close(); } catch (e) {}
            }
            return;
          }
          it.src = src;
          // Every step below can throw on a browser that has run out of
          // canvas memory. Unhandled, that rejection used to skip the
          // terminal handler, leave `preparing` true for the rest of the
          // session and freeze every row on "reading" with no message.
          try {
            // JPEG has no alpha channel, so there is nothing to sample.
            it.hasAlpha = (it.srcType === 'image/jpeg') ? false : detectAlpha(src);
            it.thumb = makeThumb(src);
            it.status = 'ready';
            // Past the budget the cached pixels go straight back and are
            // decoded again per encode. See enforceBudget and ensureSrc.
            enforceBudget();
          } catch (e) {
            it.err = 'Could not read this file';
            it.status = 'error';
            releaseSrc(it);
            it.src = null;
            if (it.srcUrl) { URL.revokeObjectURL(it.srcUrl); it.srcUrl = null; }
          }
        }, function () {
          it.err = looksHeic(it.file) ? 'HEIC' : 'Could not read this file';
          it.status = 'error';
          if (it.srcUrl) { URL.revokeObjectURL(it.srcUrl); it.srcUrl = null; }
        });
      }).catch(function () {
        // Backstop, so an item always ends with either a source or an error.
        // Anything that leaves it with neither would make next() pick it up
        // again on the following pass, for ever.
        if (it.dead) return;
        if (!it.err) { it.err = 'Could not read this file'; it.status = 'error'; }
        releaseSrc(it);
        it.src = null;
        if (it.srcUrl) { URL.revokeObjectURL(it.srcUrl); it.srcUrl = null; }
      }).then(function () {
        paintRow(it);
        updateNudges();
        settle();
        return next();
      });
    }

    // The terminal handler must run on both paths, or one throw anywhere in
    // the chain leaves the tool wedged with no way back short of a reload.
    function done() {
      if (pt !== prepToken) return;      // superseded by Clear
      preparing = false;
      var more = items.some(function (i) { return !i.src && !i.err; });
      if (more) { prepare(); return; }
      run();
    }
    next().then(done, done);
  }

  function disposeItem(it) {
    // Marks the item so any encode still in flight for it bails out instead
    // of minting an object URL nothing will ever revoke.
    it.dead = true;
    it.stale = false;
    if (it.outUrl) { URL.revokeObjectURL(it.outUrl); it.outUrl = null; }
    if (it.srcUrl) { URL.revokeObjectURL(it.srcUrl); it.srcUrl = null; }
    releaseSrc(it);
    it.src = null;
    // The decode itself keeps running; its handler sees it.dead and closes
    // what it produced. This just stops a later ensureSrc adopting it.
    it.pending = null;
    it.out = null;
    it.thumb = '';
  }

  function removeItem(it) {
    var i = items.indexOf(it);
    if (i < 0) return;
    // Captured before runToken++ invalidates the chain: that chain's terminal
    // handler bails on the token check and so never reaches finishRun(), which
    // is the only place `running` is cleared. Clear it by hand here instead.
    var wasRunning = running || !!debounceT;
    // Same as clearAll: invalidate the run first, so an encode that is
    // half way through this row cannot come back and resurrect it.
    runToken++;
    running = false;
    items.splice(i, 1);
    if (it.el && it.el.li.parentNode) it.el.li.parentNode.removeChild(it.el.li);
    if (selectedId === it.id) selectedId = null;
    disposeItem(it);
    updateTotals(); updateNudges(); updateCompare(); updateZip(); syncQuality();
    if (!items.length) setNote('Cleared. Drop another image whenever you are ready.');
    settle();
    // Only the rows an interrupted run never reached are stale. With nothing
    // in flight every surviving blob still matches the settings on screen, and
    // re-running would lock every download button for the length of a whole
    // batch because one file was dropped by mistake.
    if (wasRunning) schedule();
  }

  function clearAll() {
    runToken++;
    prepToken++;
    running = false;
    preparing = false;                // or a wedged decode would outlive Clear
    if (debounceT) { clearTimeout(debounceT); debounceT = null; }
    items.forEach(disposeItem);
    items = [];
    rejected = [];
    overflow = 0;
    jpegFallback = false;
    dlCount = 0;
    selectedId = null;
    cmp.id = null;
    while (elList.firstChild) elList.removeChild(elList.firstChild);
    elList.classList.remove('no-rowdl');
    elStats.hidden = true;
    elCompare.hidden = true;
    elImgA.removeAttribute('src');
    elImgB.removeAttribute('src');
    elFile.value = '';
    elZip.disabled = true;
    elQSize.textContent = 'Add an image to see the predicted size.';
    updateNudges();
    syncQuality();
    setNote('Cleared. Nothing was ever uploaded, so there is nothing on our side to delete.');
    settle();
  }

  /* -------------------------------------------------------------- controls */

  function qualityWord(v) {
    return v <= 55 ? 'Maximum squeeze' : v <= 75 ? 'Balanced' : v <= 88 ? 'High' : 'Near original';
  }

  function syncQuality() {
    var v = parseInt(elQ.value, 10) || 82;
    elQWord.textContent = qualityWord(v);

    var live = items.filter(function (i) { return !i.err && i.src; });
    var allPng = live.length > 0 && live.every(function (i) { return outMimeFor(i) === 'image/png'; });
    var off = S.target > 0 || allPng;

    elQ.disabled = off;
    elQCtl.classList.toggle('is-off', off);
    var msg = S.target > 0
      ? 'Quality is set automatically to hit your target.'
      : allPng ? 'PNG is lossless, so quality has no effect. Switch to JPG or WebP to shrink it.' : '';
    elQNote.textContent = msg;
    elQNote.hidden = !msg;
  }

  function syncControls() {
    elQ.value = String(Math.round(S.q * 100));
    elMW.value = String(S.mw || 0);
    if (S.target > 0 && S.target % 1048576 === 0) {
      elTargetUnit.value = 'MB'; elTargetNum.value = String(S.target / 1048576);
    } else if (S.target > 0) {
      elTargetUnit.value = 'KB'; elTargetNum.value = String(Math.round(S.target / 1024));
    } else {
      elTargetUnit.value = 'KB'; elTargetNum.value = '';
    }
    markChips(elTargetChips, 'bytes', String(S.target));
    markChips(elMWChips, 'mw', String(S.mw));
    var fb = elFmt.querySelectorAll('button[data-fmt]');
    for (var i = 0; i < fb.length; i++) {
      var on = fb[i].getAttribute('data-fmt') === S.fmt;
      fb[i].classList.toggle('active', on);
      fb[i].setAttribute('aria-checked', on ? 'true' : 'false');
      fb[i].tabIndex = on ? 0 : -1;
    }
    syncQuality();
  }

  function setPreset(key, keepValues) {
    var p = PRESETS[key];
    if (!p) return;
    S.preset = key;
    var bs = elPresets.querySelectorAll('button[data-preset]');
    for (var i = 0; i < bs.length; i++) {
      var on = bs[i].getAttribute('data-preset') === key;
      bs[i].classList.toggle('is-active', on);
      bs[i].setAttribute('aria-pressed', on ? 'true' : 'false');
    }
    elPresetLine.textContent = p.blurb;
    elCustom.hidden = (key !== 'custom');
    if (key !== 'custom' && !keepValues) {
      S.fmt = p.fmt; S.q = p.q; S.mw = p.mw; S.target = p.target;
    }
    syncControls();
  }

  function readTarget() {
    var n = parseFloat(elTargetNum.value);
    if (!isFinite(n) || n <= 0) return 0;
    return Math.round(n * (elTargetUnit.value === 'MB' ? 1048576 : 1024));
  }

  elPresets.addEventListener('click', function (e) {
    var b = e.target.closest ? e.target.closest('button[data-preset]') : null;
    if (!b) return;
    setPreset(b.getAttribute('data-preset'));
    schedule();
    settle();
  });

  elTargetNum.addEventListener('input', function () {
    S.target = readTarget();
    markChips(elTargetChips, 'bytes', String(S.target));
    syncQuality();
    schedule();
  });
  elTargetUnit.addEventListener('change', function () {
    S.target = readTarget();
    markChips(elTargetChips, 'bytes', String(S.target));
    syncQuality();
    schedule();
  });
  elTargetChips.addEventListener('click', function (e) {
    var b = e.target.closest ? e.target.closest('button[data-bytes]') : null;
    if (!b) return;
    S.target = parseInt(b.getAttribute('data-bytes'), 10) || 0;
    if (S.target > 0 && S.target % 1048576 === 0) {
      elTargetUnit.value = 'MB'; elTargetNum.value = String(S.target / 1048576);
    } else if (S.target > 0) {
      elTargetUnit.value = 'KB'; elTargetNum.value = String(Math.round(S.target / 1024));
    } else {
      elTargetNum.value = '';
    }
    markChips(elTargetChips, 'bytes', String(S.target));
    syncQuality();
    schedule();
    settle();
  });

  elQ.addEventListener('input', function () {
    S.q = (parseInt(elQ.value, 10) || 82) / 100;
    syncQuality();
    schedule();
  });

  elFmt.addEventListener('click', function (e) {
    var b = e.target.closest ? e.target.closest('button[data-fmt]') : null;
    if (!b) return;
    S.fmt = b.getAttribute('data-fmt');
    syncControls();
    schedule();
  });
  elFmt.addEventListener('keydown', function (e) {
    if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
    var all = elFmt.querySelectorAll('button[data-fmt]');
    var list = [];
    for (var i = 0; i < all.length; i++) list.push(all[i]);
    var idx = list.indexOf(document.activeElement);
    if (idx < 0) idx = 0;
    idx = (idx + (e.key === 'ArrowRight' ? 1 : -1) + list.length) % list.length;
    S.fmt = list[idx].getAttribute('data-fmt');
    syncControls();
    list[idx].focus();
    schedule();
    e.preventDefault();
  });

  elMW.addEventListener('input', function () {
    S.mw = Math.max(0, parseInt(elMW.value, 10) || 0);
    markChips(elMWChips, 'mw', String(S.mw));
    schedule();
  });
  elMWChips.addEventListener('click', function (e) {
    var b = e.target.closest ? e.target.closest('button[data-mw]') : null;
    if (!b) return;
    S.mw = parseInt(b.getAttribute('data-mw'), 10) || 0;
    elMW.value = String(S.mw);
    markChips(elMWChips, 'mw', String(S.mw));
    schedule();
    settle();
  });

  /* ----------------------------------------------------------- input paths */

  elPick.addEventListener('click', function (e) { e.stopPropagation(); elFile.click(); });
  elDrop.addEventListener('click', function () { elFile.click(); });
  elFile.addEventListener('change', function () {
    addFiles(elFile.files);
    elFile.value = '';                 // re-picking the same file must still fire
  });

  ['dragenter', 'dragover'].forEach(function (t) {
    elDrop.addEventListener(t, function (e) {
      e.preventDefault(); e.stopPropagation();
      elDrop.classList.add('is-over');
    });
  });
  ['dragleave', 'dragend'].forEach(function (t) {
    elDrop.addEventListener(t, function (e) {
      e.preventDefault();
      elDrop.classList.remove('is-over');
    });
  });
  elDrop.addEventListener('drop', function (e) {
    e.preventDefault(); e.stopPropagation();
    elDrop.classList.remove('is-over');
    addFiles(e.dataTransfer && e.dataTransfer.files);
  });
  document.addEventListener('dragover', function (e) { e.preventDefault(); });
  document.addEventListener('drop', function (e) {
    e.preventDefault();
    addFiles(e.dataTransfer && e.dataTransfer.files);
  });
  document.addEventListener('paste', function (e) {
    var cd = e.clipboardData;
    if (!cd || !cd.files || !cd.files.length) return;
    e.preventDefault();
    addFiles(cd.files);
  });

  elZip.addEventListener('click', downloadZip);
  elClear.addEventListener('click', clearAll);

  /* ---------------------------------------------------- P2 hook, heatmap */
  // A difference heatmap would live beside the compare viewport: getImageData
  // on both images at the same scale, amplify abs(a-b) per channel, paint the
  // delta into a third canvas layered inside .ic-stage and add a fourth
  // segmented mode next to SPLIT. Not built.

  /* ----------------------------------------------------------------- boot */

  setSplit(50);
  setMode('after');
  setPreset('balanced');
  updateTotals();
  settle();
})();
